const BASE='https://rentalcamera.aiorbitlab.me';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=s=>String(s||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
const url=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:null}catch(_){return null}};
const itemPath=(kind,id)=>'/'+kind+'/'+encodeURIComponent(id);
function routeForPath(path){const p=String(path||'/').split(/[?#]/)[0].replace(/\/$/,'')||'/';const kinds={'/':'home','/produk':'products','/artikel':'articles','/portfolio':'portfolio','/cart':'cart','/pesanan':'order','/cek-order':'tracking'};if(kinds[p])return {kind:kinds[p]};const m=p.match(/^\/(produk|artikel|portfolio)\/([^/]+)$/);try{return m?{kind:{produk:'product',artikel:'article',portfolio:'portfolioItem'}[m[1]],slug:decodeURIComponent(m[2])}:{kind:'missing'}}catch(_){return {kind:'missing'}}}
function buildSeo(route={},data={cfg:{},products:[],articles:[],portfolio:[]}){
 const {cfg,products,articles,portfolio}=data,g=cfg.general||{},b=cfg.business||{},name=plain(g.siteName)||'Rentcam',desc=plain(g.seoDescription||g.tagline)||'Katalog produk dan layanan rental.',org={'@type':b.streetAddress&&b.city?'LocalBusiness':'Organization','@id':BASE+'/#business',name,url:BASE,description:desc};
 const logo=url(g.logoUrl);if(logo)org.logo=logo;if(g.whatsapp)org.telephone=String(g.whatsapp);if(g.email)org.email=g.email;
 if(b.streetAddress&&b.city)org.address={'@type':'PostalAddress',streetAddress:b.streetAddress,addressLocality:b.city,...(b.region?{addressRegion:b.region}:{}),...(b.postalCode?{postalCode:b.postalCode}:{}),addressCountry:b.country||'ID'};
 if(b.serviceArea)org.areaServed=b.serviceArea;const sameAs=String(b.sameAs||'').split(/\n/).map(url).filter(Boolean);if(sameAs.length)org.sameAs=sameAs;
 let out={name,title:plain(g.seoTitle)||name,description:desc,h1:name,summary:desc,canonical:BASE+'/',robots:'index,follow,max-image-preview:large',status:200,schema:[org,{'@type':'WebSite','@id':BASE+'/#website',name,url:BASE,inLanguage:'id-ID',publisher:{'@id':org['@id']}}],business:org,verification: /^[A-Za-z0-9_-]{10,200}$/.test(cfg.search?.googleVerification||'')?cfg.search.googleVerification:null,body:''};
 const links=(rows,kind)=>'<ul>'+rows.map(p=>`<li><a href="${esc(itemPath(kind,p.id))}">${esc(p.name||p.title)}</a>${p.description||p.excerpt||p.desc?' — '+esc(plain(p.description||p.excerpt||p.desc)):''}</li>`).join('')+'</ul>';
 const crumb=(label,path)=>({'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name,url:BASE,item:BASE+'/'},{'@type':'ListItem',position:2,name:label,item:BASE+path}]});
 const notFound=()=>({...out,status:404,title:'Halaman tidak ditemukan | '+name,h1:'Halaman tidak ditemukan',summary:'Halaman ini belum tersedia atau tidak lagi diterbitkan.',robots:'noindex,follow',schema:[],body:'<a href="/produk">Lihat katalog</a>'});
 if(route.kind==='home'){out.body=`<h2>Katalog produk</h2>${links(products.slice(0,48),'produk')}<h2>Artikel</h2>${links(articles,'artikel')}`}
 else if(['products','articles','portfolio'].includes(route.kind)){
  const key=route.kind,path={products:'/produk',articles:'/artikel',portfolio:'/portfolio'}[key],title={products:cfg.copy?.catalogTitle||'Katalog Rental',articles:cfg.appearance?.articlesTitle||'Artikel & Panduan',portfolio:cfg.appearance?.portfolioTitle||'Portfolio'}[key],rows=data[key];
  out={...out,title:title+' | '+name,h1:title,canonical:BASE+path,summary:{products:cfg.copy?.catalogSubtitle,articles:cfg.appearance?.articlesSubtitle,portfolio:cfg.appearance?.portfolioSubtitle}[key]||desc,body:links(rows,path.slice(1)),schema:[org,{'@type':'CollectionPage',name:title,url:BASE+path,inLanguage:'id-ID'}, {'@type':'ItemList',itemListElement:rows.map((p,i)=>({'@type':'ListItem',position:i+1,name:p.name||p.title,url:BASE+itemPath(path.slice(1),p.id)}))}]};
 }else if(route.kind==='product'){
  const p=products.find(p=>String(p.id)===String(route.slug));if(!p)return notFound();const path=itemPath('produk',p.id),description=plain(p.seoDescription||p.description||p.geoSummary)||`Informasi rental ${p.name}. Hubungi ${name} untuk ketersediaan.`,product={'@type':'Product','@id':BASE+path+'#product',name:p.name,description,url:BASE+path};
  if(p.brand)product.brand={'@type':'Brand',name:p.brand};if(p.category)product.category=p.category;if(url(p.image))product.image=[url(p.image)];
  let price=p.price;const now=new Date().toISOString().slice(0,10);if(Number(p.discountPercent)>0&&Number(p.discountPercent)<=100&&(!p.discountStart||now>=p.discountStart)&&(!p.discountEnd||now<=p.discountEnd)&&Number.isFinite(price))price=Math.round(price*(1-Number(p.discountPercent)/100));
  if(Number.isFinite(price)&&price>=0)product.offers={'@type':'Offer',url:BASE+path,priceCurrency:'IDR',price:String(price),businessFunction:'http://purl.org/goodrelations/v1#LeaseOut',seller:{'@id':org['@id']},...(Number.isFinite(p.stock)?{availability:p.stock>0&&String(p.labelText||'').toUpperCase()!=='DISCONTINUED'?'https://schema.org/InStock':'https://schema.org/OutOfStock'}:{})};
  let body=`${url(p.image)?`<img src="${esc(url(p.image))}" alt="${esc(p.name)}" width="480" style="max-width:100%;height:auto">`:''}<p>${esc(plain(p.description))}</p>${Number.isFinite(price)?`<p>Tarif sewa: Rp${new Intl.NumberFormat('id-ID').format(price)} per hari. Konfirmasi stok dan tanggal sebelum memesan.</p>`:''}${p.geoSummary?'<h2>Ringkasan produk</h2><p>'+esc(plain(p.geoSummary))+'</p>':''}`;
  for(const [key,label] of [['included','Termasuk dalam paket'],['accessories','Aksesori']])if(Array.isArray(p[key])&&p[key].length)body+='<h2>'+label+'</h2><ul>'+p[key].map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';
  if(Array.isArray(p.spec)&&p.spec.length)body+='<h2>Spesifikasi</h2><ul>'+p.spec.map(x=>'<li>'+esc(Array.isArray(x)?x.join(': '):x)+'</li>').join('')+'</ul>';
  const pageSchema={'@type':'WebPage','@id':BASE+path+'#webpage',url:BASE+path,name:p.seoTitle||p.name,inLanguage:'id-ID',mainEntity:{'@id':product['@id']}};if(p.seoKeywords)pageSchema.keywords=String(p.seoKeywords);const topics=String(p.geoEntities||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,30);if(topics.length)pageSchema.about=topics.map(name=>({'@type':'Thing',name}));const schema=[org,product,pageSchema,crumb(p.name,path)];if(p.aeoQuestion&&p.aeoAnswer){body+=`<h2>${esc(p.aeoQuestion)}</h2><p>${esc(p.aeoAnswer)}</p>`;schema.push({'@type':'FAQPage',mainEntity:[{'@type':'Question',name:p.aeoQuestion,acceptedAnswer:{'@type':'Answer',text:p.aeoAnswer}}]})}
  out={...out,title:plain(p.seoTitle)||`Sewa ${p.name} | ${name}`,description,h1:p.name,summary:description,canonical:BASE+path,schema,body:body+'<p><a href="/produk">Kembali ke katalog</a></p>',image:url(p.image),productInfo:{id:p.id,summary:p.geoSummary||'',question:p.aeoQuestion||'',answer:p.aeoAnswer||''}};
 }else if(['article','portfolioItem'].includes(route.kind)){
  const article=route.kind==='article',p=(article?articles:portfolio).find(p=>String(p.id)===String(route.slug));if(!p)return notFound();const path=itemPath(article?'artikel':'portfolio',p.id),description=plain(p.seoDescription||p.excerpt||p.desc)||desc,image=url(p.image||p.img),schema={'@type':article?'Article':'CreativeWork',name:p.title,headline:p.title,description,url:BASE+path,mainEntityOfPage:BASE+path,publisher:{'@id':org['@id']},inLanguage:'id-ID'};
  if(image)schema.image=[image];if(article&&p.date&&!isNaN(Date.parse(p.date)))schema.datePublished=new Date(p.date).toISOString().slice(0,10);if(p.updatedAt&&!isNaN(Date.parse(p.updatedAt)))schema.dateModified=p.updatedAt;if(p.author)schema.author={'@type':'Person',name:p.author};
  out={...out,title:plain(p.seoTitle)||p.title+' | '+name,description,h1:p.title,summary:description,canonical:BASE+path,image,schema:[org,schema,crumb(p.title,path)],body:String(p.body||p.excerpt||p.desc||'').split(/\n+/).map(x=>'<p>'+esc(x)+'</p>').join('')};
 }else if(['cart','order','tracking'].includes(route.kind)){const title={cart:'Keranjang Rental',order:'Pesanan Rental',tracking:'Cek Order'}[route.kind];out={...out,title:title+' | '+name,h1:title,canonical:BASE+{cart:'/cart',order:'/pesanan',tracking:'/cek-order'}[route.kind],robots:'noindex,nofollow',schema:[]}}
 else return notFound();
 if(route.kind==='home'&&org.address)out.body+=`<h2>Lokasi & Kontak</h2><p>${esc([name,b.streetAddress,b.city,g.whatsapp,g.email].filter(Boolean).join(' · '))}</p>`;
 return out;
}
module.exports={buildSeo,routeForPath,BASE,esc};
